package com.nthexperience.desktop;

import android.app.*;
import android.content.*;
import android.content.pm.ActivityInfo;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.lang.reflect.Field;
import java.util.*;

/** All shipped presets, mixed palettes, menus, live documents and portable appearance state. */
public final class ElevenThemeSmoke extends ElevenSmoke {
    TenSettings settings;EditText note;DesktopWindow noteWindow;int combinations;
    final StringBuilder matrix=new StringBuilder("Orientation\tTheme\tApp mode\tShell mode\tResult\n");
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).putBoolean("weather_follow",false).putBoolean("eleven_initialized",true).commit();
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();
        ui(()->{home.open("@notes");noteWindow=TenSmoke.find(root,DesktopWindow.class);note=(EditText)TenSmoke.description(root,"Notepad text");note.setText("Appearance preserves this document and selection.");note.setSelection(4,13);home.open("ten-setting:themes");settings=TenSmoke.find(root,TenSettings.class);});
        List<TenThemes.Preset> themes=new ArrayList<>(TenThemes.TEN);themes.addAll(TenThemes.AERO);
        check(themes.size()==23&&TenThemes.RECORDED.size()==8,"Recorded and retained themes available");
        for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,ActivityInfo.SCREEN_ORIENTATION_PORTRAIT}){
            ui(()->home.setRequestedOrientation(orientation));SystemClock.sleep(650);waitForIdleSync();
            for(TenThemes.Preset theme:themes){
                ui(()->{settings.navigate("themes");TenThemeGallery gallery=TenSmoke.find(settings,TenThemeGallery.class);View tile=TenSmoke.description(gallery,"Apply theme: "+theme.name);check(tile!=null,"Gallery contains "+theme.name);tile.performClick();check(theme.matches(store)&&TenThemes.currentName(store).equals(theme.name),"Whole preset applies: "+theme.name);check(note.getText().toString().equals("Appearance preserves this document and selection.")&&note.getSelectionStart()==4&&note.getSelectionEnd()==13,"Document and selection survive "+theme.name);check(TenAppearance.contrast(note.getCurrentTextColor(),TenAppearance.background(home))>=4.5,"Document contrast: "+theme.name);menu(theme.name);for(boolean effects:new boolean[]{false,true}){store.prefs.edit().putBoolean("ten_transparency",effects).putBoolean("aero_transparency",effects).commit();ElevenMaterial material=ElevenMaterial.menu(home);for(int fill:material.textSurfaces())check(TenAccent.contrast(TenAccent.readableOn(TenAppearance.ink(home),material.textSurfaces()),fill)>=4.5,"Material contrast with effects "+effects);}});
                combinations++;matrix.append(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?"Portrait":"Landscape").append('\t').append(theme.name).append('\t').append(theme.appsDark()?"Dark":"Light").append('\t').append(theme.light?"Light":"Dark").append("\tPASS\n");
                if(orientation==ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE&&TenThemes.RECORDED.contains(theme))shot("eleven-theme-"+theme.name.toLowerCase(Locale.ROOT).replace(' ','-'));
            }
        }
        mixedModes();appearanceState();slideshowDraft();widgets();
        ui(()->{TenThemes.TEN.get(2).apply(store);home.applyTenAppearance();settings.navigate("colors");});shot("eleven-colors-final");
        save();result.putString("stream","PASS: Eleven themes "+checks+" assertions; "+combinations+" preset/orientation combinations, menus, all mixed app/shell modes, transparency, portable solid colors, custom/automatic accents, Widgets settings and preserved document selection\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable ex){try{save();shot("eleven-themes-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
    void menu(String name){
        try{DesktopContextMenu menu=new DesktopContextMenu(home,"Theme contrast fixture");menu.item("Enabled command","settings",()->{});menu.submenu("Submenu","folder",()->{});menu.item("Unavailable","empty",false,()->{});Field field=DesktopContextMenu.class.getDeclaredField("popup");field.setAccessible(true);View view=((PopupWindow)field.get(menu)).getContentView();TenAppearance.apply(view);audit(view);menu.dismiss();DesktopContextMenu shellMenu=new DesktopContextMenu(home,"Start button context menu");shellMenu.item("Shell command","empty",()->{});View shellView=((PopupWindow)field.get(shellMenu)).getContentView();TextView shellText=TenSmoke.text(shellView,"Shell command");check(TenAccent.contrast(shellText.getCurrentTextColor(),TenStyle.surface(home))>=4.5,"Start button menu follows independent shell mode");shellMenu.dismiss();}catch(Exception e){throw new RuntimeException(name,e);}
    }
    void audit(View view){if(Boolean.TRUE.equals(view.getTag(R.id.ten_appearance_preserve)))return;if(view instanceof TextView&&view.isEnabled()&&view.getAlpha()>.9f){TextView text=(TextView)view;try{java.lang.reflect.Method method=TenAppearance.class.getDeclaredMethod("accentSurfaces",View.class);method.setAccessible(true);int[] fills=(int[])method.invoke(null,view);for(int fill:fills)check(TenAccent.contrast(text.getCurrentTextColor(),fill)>=4.45,"Menu text contrast: "+text.getText()+" / "+Integer.toHexString(fill));}catch(ReflectiveOperationException e){throw new RuntimeException(e);}}if(view instanceof ViewGroup&&view.isEnabled())for(int i=0;i<((ViewGroup)view).getChildCount();i++)audit(((ViewGroup)view).getChildAt(i));}
    void mixedModes()throws Exception{for(boolean appDark:new boolean[]{true,false})for(boolean shellLight:new boolean[]{true,false})ui(()->{store.prefs.edit().putString("ten_shell_style","Ten").putBoolean("ten_apps_dark",appDark).putBoolean("ten_light",shellLight).commit();home.applyTenAppearance();settings.navigate("colors");menu("Mixed mode");for(int color:TenAccent.COLORS){ElevenColors.choose(store,color);menu("Accent "+ElevenColors.hex(color));}StartMenu start=TenSmoke.find(root,StartMenu.class);start.appearanceChanged();check(TenAccent.contrast(start.search.getCurrentTextColor(),((GradientDrawable)start.search.getBackground()).getColor().getDefaultColor())>=4.5,"Start search follows shell mode independently");});}
    void appearanceState()throws Exception{
        ui(()->{try{settings.navigate("colors");Switch effects=(Switch)TenSmoke.text(settings,"Transparency effects");check(effects!=null,"Single glass switch exists");boolean before=effects.isChecked();effects.performClick();check(store.prefs.getBoolean("ten_transparency",false)!=before&&store.prefs.getBoolean("aero_transparency",false)!=before,"Switch controls modern and classic surfaces");settings.navigate("background");check(TenSmoke.description(settings,"Personalize your background choice")!=null,"Background mode picker exists");store.prefs.edit().putString("eleven_background_mode","Solid color").putInt("eleven_solid_color",0xff13a8bc).commit();home.applyTenAppearance();AeroWallpaper wallpaper=home.wallpaperSurface();Bitmap pixels=Bitmap.createBitmap(wallpaper.getWidth(),wallpaper.getHeight(),Bitmap.Config.ARGB_8888);wallpaper.draw(new Canvas(pixels));check(pixels.getPixel(pixels.getWidth()/2,pixels.getHeight()/2)==0xff13a8bc,"Solid color affects actual desktop");pixels.recycle();JSONObject theme=ThemeProfiles.capture(store,"Solid appearance fixture");byte[] pack=ThemeProfiles.pack(home,theme);TenThemes.TEN.get(2).apply(store);ThemeProfiles.apply(store,ThemeProfiles.unpack(home,new ByteArrayInputStream(pack)));check(store.prefs.getString("eleven_background_mode","").equals("Solid color")&&store.prefs.getInt("eleven_solid_color",0)==0xff13a8bc,"Portable theme restores solid background");ElevenColors.choose(store,0xff123456);ElevenColors.choose(store,Color.WHITE);ElevenColors.choose(store,0xff123456);check(ElevenColors.recent(store).get(0)==0xff123456&&Collections.frequency(ElevenColors.recent(store),0xff123456)==1,"Recent colors deduplicate and preserve literal colors");store.prefs.edit().putString(ElevenColors.MODE,"Automatic").commit();home.applyTenAppearance();check(store.prefs.getInt("ten_accent",0)!=0xff123456,"Automatic accent samples actual wallpaper");DesktopBackup.Plan plan=DesktopBackup.parse(DesktopBackup.snapshot(store).toString());check(plan.values.containsKey("eleven_solid_color")&&plan.values.containsKey(ElevenColors.RECENT)&&plan.values.containsKey(ElevenColors.MODE),"Appearance preferences survive backup validation");TenThemes.TEN.get(2).apply(store);home.applyTenAppearance();}catch(Exception e){throw new RuntimeException(e);}});
    }
    void slideshowDraft()throws Exception{ui(()->{try{settings.navigate("background-slideshow");List<String> before=DesktopBackgrounds.current(store.prefs);BackgroundPicker.imported(settings.backgroundDraft,Arrays.asList("#15","#16"));settings.refreshAppearance();check(DesktopBackgrounds.current(store.prefs).equals(before),"Slideshow import remains staged");JSONObject state=new JSONObject(settings.state().toString());java.util.Iterator<String> keys=settings.backgroundDraft.keys();while(keys.hasNext()){keys.next();keys.remove();}settings.restoreState(state);check(settings.backgroundDraft.optJSONArray("selected").length()==2,"Slideshow draft survives Settings state restoration");TenSmoke.text(settings,"Save changes").performClick();check(DesktopBackgrounds.current(store.prefs).equals(Arrays.asList("#15","#16")),"Slideshow Save applies the selected pictures");BackgroundPicker.imported(settings.backgroundDraft,Arrays.asList("#17","#18"));settings.refreshAppearance();TenSmoke.text(settings,"Cancel changes").performClick();check(DesktopBackgrounds.current(store.prefs).equals(Arrays.asList("#15","#16")),"Slideshow Cancel keeps saved desktop pictures");}catch(Exception e){throw new RuntimeException(e);}});}
    void widgets()throws Exception{ui(()->{home.open("@news");View button=TenSmoke.description(root,"Widgets Settings");check(button!=null,"Widgets Settings rail exists");button.performClick();check(TenSmoke.description(root,"Widgets settings dashboard")!=null,"Settings opens inside board");Switch discover=(Switch)TenSmoke.description(root,"Discover");boolean before=discover.isChecked();discover.performClick();check(store.prefs.getBoolean("eleven_discover_enabled",true)!=before,"Discover switch persists");TenSmoke.description(root,"Widgets Widgets").performClick();check(TenSmoke.description(root,"Widgets calendar card")!=null,"Widgets page restored");});shot("eleven-widgets-settings");}
    void save()throws IOException{try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),"eleven-theme-matrix.tsv")),java.nio.charset.StandardCharsets.UTF_8)){out.write(matrix.toString());}}
}
